mapper.select:
SELECT s.id, s.exam_id, s.student_id, s.subject_id, s.class_id, s.school_id, s.score, s.is_absent, s.rank_in_class, s.rank_in_grade, s.rank_in_school, s.total_rank_in_class, s.total_rank_in_grade, s.total_rank_in_school, s.recorder_id, s.status, s.recorded_at, s.reviewed_at, s.reviewer_id, s.reject_reason, s.remark, s.created_at, s.updated_at FROM score s WHERE s.deleted = 0
AND s.exam_id = #{request.examId}
AND s.student_id = #{request.studentId}
AND s.subject_id = #{request.subjectId}
AND s.class_id = #{request.classId}
AND s.school_id = #{request.schoolId}
AND s.status = #{request.status}
AND EXISTS ( SELECT 1 FROM exam e WHERE e.id = s.exam_id AND e.status = 3 AND e.deleted = 0 )
AND EXISTS ( SELECT 1 FROM student st WHERE st.id = s.student_id AND st.name LIKE CONCAT('%', #{request.studentName}, '%') )
AND EXISTS ( SELECT 1 FROM student st WHERE st.id = s.student_id AND st.student_no LIKE CONCAT('%', #{request.studentNo}, '%') )
ORDER BY ${request.orderBy}
ASC
DESC
ORDER BY s.created_at DESC

SELECT id, exam_id, student_id, subject_id, class_id, school_id, score, is_absent, rank_in_class, rank_in_grade, rank_in_school, total_rank_in_class, total_rank_in_grade, total_rank_in_school, recorder_id, status, recorded_at, reviewed_at, reviewer_id, reject_reason, remark, created_at, updated_at FROM score WHERE deleted = 0 AND exam_id = #{examId}
AND school_id = #{schoolId}
AND student_id = #{studentId} AND subject_id = #{subjectId} LIMIT 1

SELECT
    id, exam_id, student_id, subject_id, class_id, school_id,
    score, is_absent, rank_in_class, rank_in_grade, rank_in_school,
    total_rank_in_class, total_rank_in_grade, total_rank_in_school,
    recorder_id, status, recorded_at, reviewed_at, reviewer_id, reject_reason, remark, created_at, updated_at
FROM score
WHERE deleted = 0
  AND exam_id = #{examId}

    AND school_id = #{schoolId}


    AND class_id = #{classId}


    AND subject_id = #{subjectId}

ORDER BY score DESC NULLS LAST

mapper.sql:
FROM exam_subject es
JOIN exam      e   ON e.id  = es.exam_id   AND e.deleted  = 0
JOIN subject   sub ON sub.id = es.subject_id AND sub.deleted = 0
JOIN score     s   ON s.exam_id = e.id AND s.subject_id = sub.id AND s.deleted = 0
JOIN class     sc  ON sc.id = s.class_id   AND sc.deleted = 0
WHERE es.deleted = 0
AND e.id = #{examId}
AND sc.id = #{classId}
AND sub.id = #{subjectId}
AND e.school_id = #{schoolId}
GROUP BY es.id, es.full_score, e.id, e.exam_name, e.exam_date,
         sc.id, sc.class_name, sub.id, sub.subject_name, sub.full_score
HAVING MIN(s.status) = #{status}

mapper.select:
SELECT
    s.id, s.student_id, st.student_no AS "studentNo", st.name AS "studentName",
    s.score, s.is_absent, s.remark, s.status
FROM score s
JOIN student st ON st.id = s.student_id AND st.deleted = 0
WHERE s.deleted = 0
  AND s.exam_id = #{examId}
  AND s.class_id = #{classId}
AND s.subject_id = #{subjectId}
ORDER BY st.student_no

SELECT g.id AS "gradeId", g.grade_name AS "gradeName", c.id AS "classId", c.class_name AS "className", sub.id AS "subjectId", sub.subject_name AS "subjectName", COUNT(DISTINCT cs.student_id) AS "totalCount", COUNT(DISTINCT s.id) AS "enteredCount" FROM class c JOIN grade g ON g.id = c.grade_id AND g.deleted = 0 JOIN class_student cs ON cs.class_id = c.id JOIN exam_subject es ON es.exam_id = #{examId} AND es.deleted = 0 JOIN subject sub ON sub.id = es.subject_id AND sub.deleted = 0
LEFT JOIN score s ON s.exam_id = #{examId} AND s.class_id = c.id AND s.subject_id = sub.id AND s.student_id = cs.student_id AND s.deleted = 0 WHERE c.deleted = 0 AND EXISTS ( SELECT 1 FROM exam e WHERE e.id = #{examId}
AND (e.grade_ids IS NULL OR translate(e.grade_ids, '[] ', '') = '' OR c.grade_id = ANY(string_to_array(translate(e.grade_ids, '[] ', ''), ',')::bigint[])) AND e.school_id = c.school_id ) GROUP BY g.id, g.grade_name, c.id, c.class_name, sub.id, sub.subject_name ORDER BY g.grade_code, c.class_code, sub.subject_name
